<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- achievement cards from questSnapshot */
  import { quests } from '../stores/quests.svelte.ts';
  import { getLazyListScrollRoot } from '../../formatters.ts';
  import { scheduleLazyBatch } from '../lib/scheduleLazyBatch.ts';

  const CATEGORY_BATCH = 4;

  let snap = $derived(quests.achievements);
  let visibleCategories = $state(CATEGORY_BATCH);
  let listEl = $state<HTMLElement | null>(null);
  let sentinelEl = $state<HTMLDivElement | null>(null);

  let categories = $derived(snap.categories.slice(0, visibleCategories));
  let hasMore = $derived(visibleCategories < snap.categories.length);

  $effect(() => {
    snap.categories;
    visibleCategories = CATEGORY_BATCH;
  });

  $effect(() => {
    if (!sentinelEl || !hasMore) return;
    const scrollRoot = getLazyListScrollRoot(listEl, '.secondary-content');
    const io = new IntersectionObserver(
      (entries) => {
        if (!entries.some((e) => e.isIntersecting)) return;
        const len = snap.categories.length;
        scheduleLazyBatch(() => {
          visibleCategories = Math.min(visibleCategories + CATEGORY_BATCH, len);
        });
      },
      { root: scrollRoot, rootMargin: '200px', threshold: 0 },
    );
    io.observe(sentinelEl);
    return () => io.disconnect();
  });
</script>

{#if snap.emptyHtml}
  <!-- svelte-ignore a11y_no_static_element_interactions -->
  <div>{@html snap.emptyHtml}</div>
{:else}
  <div bind:this={listEl}>
    {#each categories as cat (cat.categoryId)}
      <section class="achievement-category-section">
        <h4 class="achievement-category-title">{cat.title}</h4>
        <div class="achievement-category-list">
          {#each cat.cards as card (card.achievementKey)}
            <div class={card.cardClass}>
              {@html card.cardHtml}
            </div>
          {/each}
        </div>
      </section>
    {/each}
    {#if hasMore}
      <div bind:this={sentinelEl} class="storage-scroll-sentinel" aria-hidden="true"></div>
    {/if}
  </div>
{/if}
